45	
46	export interface GeoItemStyleOption<TCbParams = never> extends ItemStyleOption<TCbParams> {
47	    areaColor?: ZRColor;
48	};
49	interface GeoLabelOption extends LabelOption {
50	    formatter?: string | ((params: GeoLabelFormatterDataParams) => string);
51	}
52	export interface GeoStateOption {
53	    itemStyle?: GeoItemStyleOption
54	    // FIXME:TS formatter?
55	    label?: GeoLabelOption
56	}
57	interface GeoLabelFormatterDataParams {
58	    name: string;
59	    status: DisplayState;
60	}
61	
62	export interface RegionOption extends GeoStateOption, StatesOptionMixin<GeoStateOption, StatesMixinBase> {
63	    name?: string
64	    selected?: boolean
65	    tooltip?: CommonTooltipOption<GeoTooltipFormatterParams>
66	}
67	
68	/**
69	 * @deprecated Use `RegionOption` instead.
70	 */
71	export interface RegoinOption extends RegionOption {}
72	
73	export interface GeoTooltipFormatterParams {
74	    componentType: 'geo'
75	    geoIndex: number
76	    name: string
77	    $vars: ['name']
78	}
79	
80	
81	export interface GeoCommonOptionMixin extends RoamOptionMixin {
82	    // Map name
83	    map: string;
84	
85	    // Aspect is width / height. Inited to be geoJson bbox aspect
86	    // This parameter is used for scale this aspect
87	    aspectScale?: number;
88	
89	    // Layout with center and size
90	    // If you want to put map in a fixed size box with right aspect ratio
91	    // This two properties may be more convenient
92	    // Like: `40` or `'50%'`.
93	    layoutCenter?: (number | string)[];
94	    // Like: `40` or `'50%'`.
95	    layoutSize?: number | string;
96	
97	    // Define left-top, right-bottom lng/lat coords to control view
98	    // For example, [ [180, 90], [-180, -90] ]
99	    // higher priority than center and zoom
100	    boundingCoords?: number[][];
101	
102	    nameMap?: NameMap;
103	    nameProperty?: string;
104	
105	    /**
106	     * Use raw projection by default
107	     * Only available for GeoJSON source.
108	     *
109	     * NOTE: `center` needs to be the projected coord if projection is used.
110	     */
111	    projection?: GeoProjection;
112	}
113	
114	export interface GeoOption extends
115	    ComponentOption,
116	    BoxLayoutOptionMixin,
117	    // For lens animation on geo.
118	    AnimationOptionMixin,
119	    GeoCommonOptionMixin,
120	    StatesOptionMixin<GeoStateOption, StatesMixinBase>, GeoStateOption {
121	    mainType?: 'geo';
122	
123	    show?: boolean;
124	    silent?: boolean;
125	
126	    regions?: RegionOption[];
127	
128	    stateAnimation?: AnimationOptionMixin
129	
130	    selectedMode?: 'single' | 'multiple' | boolean
131	    selectedMap?: Dictionary<boolean>
132	
133	    tooltip?: CommonTooltipOption<GeoTooltipFormatterParams>
134	}
135	
136	class GeoModel extends ComponentModel<GeoOption> {
137	
138	    static type = 'geo';
139	    readonly type = GeoModel.type;
140	
141	    coordinateSystem: Geo;
142	
143	    static layoutMode = 'box' as const;
144	
145	    private _optionModelMap: zrUtil.HashMap<Model<RegionOption>>;
146	
147	    static defaultOption: GeoOption = {
148	
149	        // zlevel: 0,
150	
151	        z: 0,
152	
153	        show: true,
154	
155	        left: 'center',
156	
157	        top: 'center',
158	
159	        // Default value:
160	        // for geoSVG source: 1,
161	        // for geoJSON source: 0.75.
162	        aspectScale: null,
163	
164	        // /// Layout with center and size
165	        // If you want to put map in a fixed size box with right aspect ratio
166	        // This two properties may be more convenient
167	        // layoutCenter: [50%, 50%]
168	        // layoutSize: 100
169	
170	        silent: false,
171	
172	        // Map type
173	        map: '',
174	
175	        // Define left-top, right-bottom coords to control view
176	        // For example, [ [180, 90], [-180, -90] ]
177	        boundingCoords: null,
178	
179	        // Default on center of map
180	        center: null,
181	
182	        zoom: 1,
183	
184	        scaleLimit: null,
185	
186	        // selectedMode: false
187	
188	        label: {
189	            show: false,
190	            color: '#000'
191	        },
192	
193	        itemStyle: {
194	            borderWidth: 0.5,
195	            borderColor: '#444'
196	            // Default color:
197	            // + geoJSON: #eee
198	            // + geoSVG: null (use SVG original `fill`)
199	            // color: '#eee'
200	        },
201	
202	        emphasis: {
203	            label: {
204	                show: true,
205	                color: 'rgb(100,0,0)'
206	            },
207	            itemStyle: {
208	                color: 'rgba(255,215,0,0.8)'
209	            }
210	        },
211	
212	        select: {
213	            label: {
214	                show: true,
215	                color: 'rgb(100,0,0)'
216	            },
217	            itemStyle: {
218	                color: 'rgba(255,215,0,0.8)'
219	            }
220	        },
221	
222	        regions: []
223	
224	        // tooltip: {
225	        //     show: false
226	        // }
227	    };
228	
229	    init(option: GeoOption, parentModel: Model, ecModel: GlobalModel): void {
230	        const source = geoSourceManager.getGeoResource(option.map);
231	        if (source && source.type === 'geoJSON') {
232	            const itemStyle = option.itemStyle = option.itemStyle || {};
233	            if (!('color' in itemStyle)) {
234	                itemStyle.color = '#eee';
235	            }
236	        }
237	
238	        this.mergeDefaultAndTheme(option, ecModel);
239	
240	        // Default label emphasis `show`
241	        modelUtil.defaultEmphasis(option, 'label', ['show']);
242	    }
243	
244	    optionUpdated(): void {
245	        const option = this.option;
246	
247	        option.regions = geoCreator.getFilledRegions(
248	            option.regions, option.map, option.nameMap, option.nameProperty
249	        );
250	
251	        const selectedMap: Dictionary<boolean> = {};
252	        this._optionModelMap = zrUtil.reduce(option.regions || [], (optionModelMap, regionOpt) => {
253	            const regionName = regionOpt.name;
254	            if (regionName) {
255	                optionModelMap.set(regionName, new Model(regionOpt, this, this.ecModel));
256	                if (regionOpt.selected) {
257	                    selectedMap[regionName] = true;
258	                }
259	            }
260	            return optionModelMap;
261	        }, zrUtil.createHashMap());
262	
263	        if (!option.selectedMap) {
264	            option.selectedMap = selectedMap;
265	        }
266	    }
267	
268	    /**
269	     * Get model of region.
270	     */
271	    getRegionModel(name: string): Model<RegionOption> {
272	        return this._optionModelMap.get(name) || new Model(null, this, this.ecModel);
273	    }
274	
275	    /**
276	     * Format label
277	     * @param name Region name
278	     */
279	    getFormattedLabel(name: string, status?: DisplayState) {
280	        const regionModel = this.getRegionModel(name);
281	        const formatter = status === 'normal'
282	            ? regionModel.get(['label', 'formatter'])
283	            : regionModel.get(['emphasis', 'label', 'formatter']);
284	        const params = {
285	            name: name
286	        } as GeoLabelFormatterDataParams;
287	        if (zrUtil.isFunction(formatter)) {
288	            params.status = status;
289	            return formatter(params);
290	        }
291	        else if (zrUtil.isString(formatter)) {
292	            return formatter.replace('{a}', name != null ? name : '');
293	        }
294	    }
295	
296	    setZoom(zoom: number): void {
297	        this.option.zoom = zoom;
298	    }
299	
300	    setCenter(center: number[]): void {
301	        this.option.center = center;
302	    }
303	
304	    // PENGING If selectedMode is null ?
305	    select(name?: string): void {
306	        const option = this.option;
307	        const selectedMode = option.selectedMode;
308	        if (!selectedMode) {
309	            return;
310	        }
311	        if (selectedMode !== 'multiple') {
312	            option.selectedMap = null;
313	        }
314	
315	        const selectedMap = option.selectedMap || (option.selectedMap = {});
316	        selectedMap[name] = true;
317	    }
318	
319	    unSelect(name?: string): void {
320	        const selectedMap = this.option.selectedMap;
321	        if (selectedMap) {
322	            selectedMap[name] = false;
323	        }
324	    }
325	
326	    toggleSelected(name?: string): void {
327	        this[this.isSelected(name) ? 'unSelect' : 'select'](name);
328	    }
329	
330	    isSelected(name?: string): boolean {
331	        const selectedMap = this.option.selectedMap;
332	        return !!(selectedMap && selectedMap[name]);
333	    }
334	
335	}
336	
337	export default GeoModel;

