21	import MapDraw from '../helper/MapDraw';
22	import ComponentView from '../../view/Component';
23	import GlobalModel from '../../model/Global';
24	import ExtensionAPI from '../../core/ExtensionAPI';
25	import GeoModel from '../../coord/geo/GeoModel';
26	import { Payload, ZRElementEvent, ECEventData } from '../../util/types';
27	import { getECData } from '../../util/innerStore';
28	import { findEventDispatcher } from '../../util/event';
29	import Element from 'zrender/src/Element';
30	
31	class GeoView extends ComponentView {
32	
33	    static type = 'geo' as const;
34	    readonly type = GeoView.type;
35	
36	    private _mapDraw: MapDraw;
37	
38	    private _api: ExtensionAPI;
39	
40	    private _model: GeoModel;
41	
42	    focusBlurEnabled = true;
43	
44	    init(ecModel: GlobalModel, api: ExtensionAPI) {
45	        this._api = api;
46	    }
47	
48	    render(
49	        geoModel: GeoModel, ecModel: GlobalModel, api: ExtensionAPI, payload: Payload
50	    ): void {
51	        this._model = geoModel;
52	
53	        if (!geoModel.get('show')) {
54	            this._mapDraw && this._mapDraw.remove();
55	            this._mapDraw = null;
56	            return;
57	        }
58	
59	        if (!this._mapDraw) {
60	            this._mapDraw = new MapDraw(api);
61	        }
62	        const mapDraw = this._mapDraw;
63	        mapDraw.draw(geoModel, ecModel, api, this, payload);
64	        mapDraw.group.on('click', this._handleRegionClick, this);
65	        mapDraw.group.silent = geoModel.get('silent');
66	        this.group.add(mapDraw.group);
67	        this.updateSelectStatus(geoModel, ecModel, api);
68	    }
69	
70	    private _handleRegionClick(e: ZRElementEvent) {
71	        let eventData: ECEventData;
72	
73	        findEventDispatcher(e.target, current => {
74	            return (eventData = getECData(current).eventData) != null;
75	        }, true);
76	
77	        if (eventData) {
78	            this._api.dispatchAction({
79	                type: 'geoToggleSelect',
80	                geoId: this._model.id,
81	                name: eventData.name
82	            });
83	        }
84	    }
85	
86	    updateSelectStatus(model: GeoModel, ecModel: GlobalModel, api: ExtensionAPI) {
87	        this._mapDraw.group.traverse((node) => {
88	            const eventData = getECData(node).eventData;
89	            if (eventData) {
90	                this._model.isSelected(eventData.name)
91	                    ? api.enterSelect(node) : api.leaveSelect(node);
92	                // No need to traverse children.
93	                return true;
94	            }
95	        });
96	    }
97	
98	    findHighDownDispatchers(name: string): Element[] {
99	        return this._mapDraw && this._mapDraw.findHighDownDispatchers(name, this._model);
100	    }
101	
102	    dispose(): void {
103	        this._mapDraw && this._mapDraw.remove();
104	    }
105	
106	}
107	
108	export default GeoView;

