553	    private _updateController(
554	        this: MapDraw, mapOrGeoModel: GeoModel | MapSeries, ecModel: GlobalModel, api: ExtensionAPI
555	    ): void {
556	        const geo = mapOrGeoModel.coordinateSystem;
557	        const controller = this._controller;
558	        const controllerHost = this._controllerHost;
559	
560	        // @ts-ignore FIXME:TS
561	        controllerHost.zoomLimit = mapOrGeoModel.get('scaleLimit');
562	        controllerHost.zoom = geo.getZoom();
563	
564	        // roamType is will be set default true if it is null
565	        // @ts-ignore FIXME:TS
566	        controller.enable(mapOrGeoModel.get('roam') || false);
567	        const mainType = mapOrGeoModel.mainType;
568	
569	        function makeActionBase(): Payload {
570	            const action = {
571	                type: 'geoRoam',
572	                componentType: mainType
573	            } as Payload;
574	            action[mainType + 'Id'] = mapOrGeoModel.id;
575	            return action;
576	        }
577	
578	        controller.off('pan').on('pan', function (e) {
579	            this._mouseDownFlag = false;
580	
581	            roamHelper.updateViewOnPan(controllerHost, e.dx, e.dy);
582	
583	            api.dispatchAction(zrUtil.extend(makeActionBase(), {
584	                dx: e.dx,
585	                dy: e.dy,
586	                animation: {
587	                    duration: 0
588	                }
589	            }));
590	        }, this);
591	
592	        controller.off('zoom').on('zoom', function (e) {
593	            this._mouseDownFlag = false;
594	
595	            roamHelper.updateViewOnZoom(controllerHost, e.scale, e.originX, e.originY);
596	
597	            api.dispatchAction(zrUtil.extend(makeActionBase(), {
598	                zoom: e.scale,
599	                originX: e.originX,
600	                originY: e.originY,
601	                animation: {
602	                    duration: 0
603	                }
604	            }));
605	
606	        }, this);
607	
608	        controller.setPointerChecker(function (e, x, y) {
609	            return geo.containPoint([x, y])
610	                && !onIrrelevantElement(e, api, mapOrGeoModel);
611	        });
612	    }
613	
614	    /**
615	     * FIXME: this is a temporarily workaround.
616	     * When `geoRoam` the elements need to be reset in `MapView['render']`, because the props like
617	     * `ignore` might have been modified by `LabelManager`, and `LabelManager#addLabelsOfSeries`
618	     * will subsequently cache `defaultAttr` like `ignore`. If do not do this reset, the modified
619	     * props will have no chance to be restored.
620	     * Note: This reset should be after `clearStates` in `renderSeries` because `useStates` in
621	     * `renderSeries` will cache the modified `ignore` to `el._normalState`.
622	     * TODO:
623	     * Use clone/immutable in `LabelManager`?
624	     */
625	    resetForLabelLayout() {
626	        this.group.traverse(el => {
627	            const label = el.getTextContent();
628	            if (label) {
629	                label.ignore = mapLabelRaw(label).ignore;
630	            }
631	        });
632	    }
