634	    private _updateMapSelectHandler(
635	        mapOrGeoModel: GeoModel | MapSeries,
636	        regionsGroup: RegionsGroup,
637	        api: ExtensionAPI,
638	        fromView: MapView | GeoView
639	    ): void {
640	        const mapDraw = this;
641	
642	        regionsGroup.off('mousedown');
643	        regionsGroup.off('click');
